const {NAVER_ID,NAVER_SECRET}=$input.first().json;
if(!NAVER_ID||!NAVER_SECRET)throw Error('네이버 NCP ID·Secret을 입력하세요.');
return Array.from({length:20},(_,i)=>({json:{
 url:'https://naverapihub.apigw.ntruss.com/search/v1/kin?query='+encodeURIComponent('LG 광파오븐')+'&display=50&sort=sim&start='+(i*50+1),
 headers:{'X-NCP-APIGW-API-KEY-ID':NAVER_ID,'X-NCP-APIGW-API-KEY':NAVER_SECRET}
}}));

const results=$input.all(); const rows=new Map(), totals=[];
let success=0;
for(const {json:r} of results){
 const b=r.body;
 if(Number(r.statusCode)!==200||!Array.isArray(b?.items))continue;
 success++;if(Number.isFinite(b.total))totals.push(b.total);
 for(const v of b.items){
  const link=String(v.link||'');
  if(!/^https?:\/\/(?:m\.)?kin\.naver\.com\/qna\/detail\.naver\?/i.test(link))continue;
  const id=link.match(/[?&]docId=(\d+)(?:[&#]|$)/i)?.[1];
  if(id&&!rows.has(id))rows.set(id,{title:String(v.title||'').replace(/<\/?b>/gi,'').replace(/&quot;/g,'"').replace(/&amp;/g,'&'),link,url:link.replace(/^https?:\/\/(?:m\.)?kin\.naver\.com/i,'https://kin.naver.com')});
 }
}
if(!success)throw Error('지식iN 검색 응답을 읽지 못했습니다. 검색 API 호출의 HTTP 상태를 확인하세요.');
return [{json:{rows:[...rows.values()],total:totals[0]??null,success,failed:results.length-success}}];

const report=$input.first().json;
 const esc=s=>String(s??'').replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g,'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;');
 const columns=['제목','질문자 본문','원본 링크'];
 const specs=[{name:'검색건수',columns:['항목','건수'],rows:report.summary,widths:[50,18],linkColumn:-1},{name:'질문목록',columns,rows:report.cases,widths:[48,110,60],linkColumn:2}];
 const files=[];const put=(name,text)=>files.push({name,data:Buffer.from(text,'utf8')});
 const letter=i=>{let s='';for(i++;i;i=Math.floor((i-1)/26))s=String.fromCharCode(65+(i-1)%26)+s;return s;};
 for(const [index,spec]of specs.entries()){const rows=[spec.columns,...spec.rows.map(r=>spec.columns.map(c=>r[c]??''))],links=[];
  const xmlRows=rows.map((row,i)=>'<row r="'+(i+1)+'" ht="'+(i===0?28:spec.linkColumn<0?46:110)+'" customHeight="1">'+row.map((value,j)=>{const ref=letter(j)+(i+1),style=i===0?1:j===spec.linkColumn?3:2;if(i&&j===spec.linkColumn&&/^https?:\/\//i.test(String(value)))links.push({ref,url:String(value),id:'h'+i});if(typeof value==='number'&&Number.isFinite(value))return '<c r="'+ref+'" s="'+style+'"><v>'+value+'</v></c>';return '<c r="'+ref+'" s="'+style+'" t="inlineStr"><is><t xml:space="preserve">'+esc(String(value).slice(0,32700))+'</t></is></c>';}).join('')+'</row>').join('');
  const sheet='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><dimension ref="A1:'+letter(spec.columns.length-1)+rows.length+'"/><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="20"/><cols>'+spec.widths.map((width,j)=>'<col min="'+(j+1)+'" max="'+(j+1)+'" width="'+width+'" customWidth="1"/>').join('')+'</cols><sheetData>'+xmlRows+'</sheetData><autoFilter ref="A1:'+letter(spec.columns.length-1)+rows.length+'"/>'+(links.length?'<hyperlinks>'+links.map(l=>'<hyperlink ref="'+l.ref+'" r:id="'+l.id+'"/>').join('')+'</hyperlinks>':'')+'</worksheet>';
  put('xl/worksheets/sheet'+(index+1)+'.xml',sheet);if(links.length)put('xl/worksheets/_rels/sheet'+(index+1)+'.xml.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+links.map(l=>'<Relationship Id="'+l.id+'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink" Target="'+esc(l.url)+'" TargetMode="External"/>').join('')+'</Relationships>');
 }
 put('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'+specs.map((_,i)=>'<Override PartName="/xl/worksheets/sheet'+(i+1)+'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>').join('')+'</Types>');
 put('_rels/.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
 put('xl/workbook.xml','<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>'+specs.map((s,i)=>'<sheet name="'+esc(s.name)+'" sheetId="'+(i+1)+'" r:id="rId'+(i+1)+'"/>').join('')+'</sheets></workbook>');
 put('xl/_rels/workbook.xml.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+specs.map((_,i)=>'<Relationship Id="rId'+(i+1)+'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet'+(i+1)+'.xml"/>').join('')+'<Relationship Id="styles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>');
 put('xl/styles.xml','<?xml version="1.0" encoding="UTF-8"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="3"><font><sz val="11"/><name val="맑은 고딕"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="맑은 고딕"/></font><font><color rgb="FF0563C1"/><u/><sz val="11"/><name val="맑은 고딕"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF263D4F"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="4"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf><xf numFmtId="0" fontId="2" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>');
 const crcTable=Array.from({length:256},(_,n)=>{let c=n;for(let k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;return c>>>0;});const crc32=data=>{let c=0xFFFFFFFF;for(const byte of data)c=crcTable[(c^byte)&255]^(c>>>8);return (c^0xFFFFFFFF)>>>0;};
 const parts=[],central=[];let offset=0;for(const f of files){const name=Buffer.from(f.name,'utf8'),crc=crc32(f.data),h=Buffer.alloc(30);h.writeUInt32LE(0x04034b50,0);h.writeUInt16LE(20,4);h.writeUInt16LE(0x0800,6);h.writeUInt16LE(0,8);h.writeUInt16LE(0x21,12);h.writeUInt32LE(crc,14);h.writeUInt32LE(f.data.length,18);h.writeUInt32LE(f.data.length,22);h.writeUInt16LE(name.length,26);parts.push(h,name,f.data);const c=Buffer.alloc(46);c.writeUInt32LE(0x02014b50,0);c.writeUInt16LE(20,4);c.writeUInt16LE(20,6);c.writeUInt16LE(0x0800,8);c.writeUInt16LE(0x21,14);c.writeUInt32LE(crc,16);c.writeUInt32LE(f.data.length,20);c.writeUInt32LE(f.data.length,24);c.writeUInt16LE(name.length,28);c.writeUInt32LE(offset,42);central.push(c,name);offset+=h.length+name.length+f.data.length;}
 const directory=Buffer.concat(central),end=Buffer.alloc(22);end.writeUInt32LE(0x06054b50,0);end.writeUInt16LE(files.length,8);end.writeUInt16LE(files.length,10);end.writeUInt32LE(directory.length,12);end.writeUInt32LE(offset,16);const xlsx=Buffer.concat([...parts,directory,end]);const name='lg-lightwave-oven-voc-'+report.collected_at.replace(/[:.]/g,'-')+'.xlsx';
 const file={data:xlsx.toString('base64'),mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',fileName:name,fileExtension:'xlsx'};
 return [{json:{file_name:name,sample:report.cases.length,bytes:xlsx.length},binary:{data:file}}];

const search=$('표본 집계').first().json, req=$('원문 요청 준비').all(), res=$('공개 원문 요청').all();
const cases=$input.all().flatMap((x,i)=>{
 const r=req[i]?.json;if(!r||r.skip)return [];
 return [{제목:r.title,'질문자 본문':Number(res[i]?.json.statusCode)===200?String(x.json.kinQuestion||'').trim():'','원본 링크':r.link}];
});
const fetched=res.filter(x=>Number(x.json.statusCode)===200&&[x.json.questionHtml,x.json.data,x.json.body].some(v=>typeof v==='string'&&v.trim())).length;
const found=cases.filter(r=>r['질문자 본문']).length;
const summary=[{항목:'지식iN API 전체 검색 건수',건수:search.total??'미제공'},{항목:'최대 20페이지 수집 질문 (중복 제거)',건수:search.rows.length},{항목:'질문자 본문 확보',건수:found},{항목:'HTTP 200 HTML 확보',건수:fetched},{항목:'본문 미확보',건수:cases.length-found},{항목:'검색 실패 페이지',건수:search.failed}];
return [{json:{cases,summary,collected_at:new Date().toISOString()}}];
